"""Independent re-implementation (plain python, no pandas) of core identities from the raw CSV."""
import csv, os
ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), "..", ".."))
D = {}
for r in csv.DictReader(open(os.path.join(ROOT, "data/raw/annual_reported_long.csv"), encoding="utf-8")):
    if r["value"] != "":
        D[(r["field"], int(r["year"]))] = float(r["value"])
Y = [2022, 2023, 2024, 2025]
TOL = 0.02

def test_balance_stock_flow():
    for y in Y:
        assert abs(D["contrib_balance", y] - (D["contrib_balance", y-1] + D["contrib_flow", y] - D["withdraw_flow", y])) <= TOL

def test_cumulative_identities():
    for y in Y:
        assert abs(D["contrib_cum", y] - D["contrib_cum", y-1] - D["contrib_flow", y]) <= TOL
        assert abs(D["withdraw_cum", y] - D["withdraw_cum", y-1] - D["withdraw_flow", y]) <= TOL
        assert abs(D["loan_cum_amount", y] - D["loan_cum_amount", y-1] - D["loan_issued", y]) <= TOL
        assert abs(D["contrib_balance", y] - (D["contrib_cum", y] - D["withdraw_cum", y])) <= TOL

def test_loan_roll_forward():
    for y in (2022, 2023, 2024):
        assert abs(D["loan_balance", y] - (D["loan_balance", y-1] + D["loan_issued", y] - D["loan_repaid", y])) <= TOL

def test_income_statement_and_allocation():
    for y in (2021, 2022, 2023, 2024):
        assert abs(D["surplus_total", y] - (D["income_total", y] - D["expense_total", y])) <= TOL
        assert abs(D["surplus_total", y] - (D["alloc_risk", y] + D["alloc_mgmt", y] + D["alloc_rental_fund", y])) <= TOL

def test_reserve_rollforward_no_writeoff():
    for y in (2022, 2023, 2024):
        assert abs(D["risk_reserve_balance", y] - D["risk_reserve_balance", y-1] - D["alloc_risk", y]) <= TOL

def test_reported_rate_reproduced():
    for y in (2022, 2023, 2024):
        avg = (D["contrib_balance", y] + D["contrib_balance", y-1]) / 2
        assert abs(100 * D["surplus_hpf", y] / avg - D["surplus_rate_pct", y]) <= 0.011

def test_2025_partial_yoy_matches_press_figures():
    assert abs(100 * (D["contrib_flow", 2025] / D["contrib_flow", 2024] - 1) - 2.67) < 0.01
    assert abs(100 * (D["withdraw_flow", 2025] / D["withdraw_flow", 2024] - 1) - 8.78) < 0.01
    assert abs(100 * D["withdraw_flow", 2025] / D["contrib_flow", 2025] - 69.18) < 0.01

def test_no_unit_or_sign_anomalies():
    for (f, y), v in D.items():
        assert v >= 0, (f, y)
EOF
